package com.smartbus.operations.repository; import com.smartbus.operations.entity.AttendanceRecord; import java.time.LocalDate; import java.util.*; import org.springframework.data.jpa.repository.JpaRepository; public interface AttendanceRecordRepository extends JpaRepository<AttendanceRecord,UUID>{ Optional<AttendanceRecord> findByStudentIdAndAttendanceDate(UUID studentId, LocalDate date); List<AttendanceRecord> findByAttendanceDateOrderByScannedAtDesc(LocalDate date); }
